/** Retained as a tombstone for old callers; never binds or launches a browser. */
export default {
  fetch(): Response {
    return Response.json(
      {
        code: 'BROWSER_SERVICE_RETIRED',
        message:
          'Cloudflare browser execution is disabled. App covers are generated by GitHub Actions; language detection reads static HTML.',
      },
      { status: 410, headers: { 'Cache-Control': 'no-store' } }
    );
  },
};
